<?php $pageTitle = 'Private ballot'; include __DIR__ . '/partials/header.php'; ?>
<section class="ballot-header"><p class="eyebrow">Private voting screen</p><h1><?= htmlspecialchars($electionService->getCurrentElection()['name'] ?? 'SRC Election', ENT_QUOTES, 'UTF-8') ?></h1><p class="muted">Your identity is not shown on this screen. Select one candidate for each position.</p></section>
<form method="post" action="/voting/ballot" class="ballot-form"><?php foreach ($ballot as $section): ?><fieldset class="panel"><legend><?= htmlspecialchars($section['position']['name'], ENT_QUOTES, 'UTF-8') ?></legend><?php foreach ($section['candidates'] as $candidate): ?><label class="candidate-option"><input type="radio" name="vote[<?= (int) $section['position']['id'] ?>]" value="<?= (int) $candidate['id'] ?>" required><span><?= htmlspecialchars($candidate['first_name'] . ' ' . $candidate['last_name'], ENT_QUOTES, 'UTF-8') ?><small><?= htmlspecialchars($candidate['programme'], ENT_QUOTES, 'UTF-8') ?></small></span></label><?php endforeach; ?><?php if (!$section['candidates']): ?><p class="muted">No eligible candidates for this position.</p><?php endif; ?></fieldset><?php endforeach; ?><button class="button button-primary" type="submit">Review ballot</button></form>
